func RequirePermission(e *casbin.Enforcer, obj, act string) func(http.Handler) http.Handler {
    return func(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            sub, _ := r.Context().Value(principalKey).(string)
            ok, err := e.Enforce(sub, obj, act)
            if err != nil || !ok {                       // fail closed
                http.Error(w, "forbidden", http.StatusForbidden)
                return
            }
            next.ServeHTTP(w, r)                         // enforcement passes
        })
    }
}
